const r=$input.first()?.json??{};
if(r.code!==0&&r.code!=='0')throw new Error('PLM_COMMAND_EXIT_FAILED');
let v;try{v=JSON.parse(String(r.stdout??'').split(/\r?\n/).reverse().find(x=>x.trim().startsWith('{'))??'');}catch{throw new Error('PLM_RESULT_INVALID');}
if(v.status!=='SUCCESS'||v.source!=='A1-PLM'||v.interfaces!==2||typeof v.snapshotId!=='string'||!/^[0-9a-f]{8}-[0-9a-f]{4}-7[0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(v.snapshotId))throw new Error('PLM_SNAPSHOT_NOT_VERIFIED');
for(const key of ['systemCount','detailCount','milestoneCount','taskCount'])if(!Number.isSafeInteger(v[key])||v[key]<0)throw new Error('PLM_COUNT_INVALID');
if(v.detailCount>v.systemCount)throw new Error('PLM_SCOPE_COUNT_INVALID');
return [{json:v}];
